const pptxgen = require("pptxgenjs");
const fs = require('fs');

async function createDeck() {
    let pres = new pptxgen();
    pres.layout = 'LAYOUT_16x9'; 
    pres.author = 'METR';
    pres.title = 'Measuring AI Ability to Complete Long Software Tasks';

    // Define palettes
    const colors = {
        primary: "1E293B", // Dark slate
        secondary: "334155", // Lighter slate
        accent: "2563EB", // Blue
        lightBg: "F8FAFC",
        white: "FFFFFF",
        grayLine: "E2E8F0"
    };

    pres.defineSlideMaster({
        title: 'MASTER_SLIDE',
        background: { color: colors.lightBg },
        objects: [
            { rect: { x: 0, y: 0, w: 10, h: 0.8, fill: { color: colors.primary } } },
            { rect: { x: 0, y: 0.8, w: 10, h: 0.05, fill: { color: colors.accent } } },
            { placeholder: { options: { name: 'title', type: 'title', x: 0.5, y: 0.15, w: 9, h: 0.5, color: colors.white, fontSize: 24, fontFace: 'Segoe UI', bold: true, align: 'left', valign: 'middle', margin: 0 } } },
            // footer
            { text: { text: "Measuring AI Ability to Complete Long Software Tasks | METR 2025", options: { x: 0.5, y: 5.3, w: 9, h: 0.2, color: "94A3B8", fontSize: 10, fontFace: 'Segoe UI', align: 'left' } } },
            { text: { text: "Source: https://arxiv.org/abs/2503.14499", options: { x: 0.5, y: 5.3, w: 9, h: 0.2, color: "94A3B8", fontSize: 10, fontFace: 'Segoe UI', align: 'right' } } }
        ]
    });

    const getShadow = () => ({ type: "outer", color: "000000", blur: 4, offset: 2, angle: 45, opacity: 0.1 });

    // SLIDE 1: Title
    let slide1 = pres.addSlide();
    slide1.background = { color: colors.primary };
    slide1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.2, fill: { color: colors.accent } });

    slide1.addText("Measuring AI Ability to Complete Long Software Tasks", {
        x: 1, y: 1.5, w: 8, h: 1.5,
        fontSize: 44, color: colors.white, fontFace: 'Segoe UI', bold: true, breakLine: true
    });
    slide1.addText("Time Horizon Doubling Every 7 Months", {
        x: 1, y: 3.0, w: 8, h: 0.5,
        fontSize: 24, color: "60A5FA", fontFace: 'Segoe UI', bold: true
    });
    slide1.addText([
        { text: "Authors: Thomas Kwa, Ben West, Joel Becker, et al.", options: { breakLine: true } },
        { text: "Model Evaluation & Threat Research (METR)", options: { breakLine: true } },
        { text: "March 2025" }
    ], {
        x: 1, y: 4.0, w: 8, h: 1,
        fontSize: 16, color: "94A3B8", fontFace: 'Segoe UI'
    });

    // SLIDE 2: Methodology
    let slide2 = pres.addSlide({ masterName: "MASTER_SLIDE" });
    slide2.addText("A New Metric: 50% Task-Completion Time Horizon", { placeholder: "title" });

    // 3 steps on the left
    slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 4.2, h: 1.0, fill: { color: colors.white }, shadow: getShadow() });
    slide2.addText([
        { text: "Step 1", options: { fontSize: 12, color: colors.accent, bold: true, breakLine: true } },
        { text: "Assemble diverse task suite", options: { fontSize: 16, color: colors.primary, bold: true, breakLine: true } },
        { text: "170 software/research tasks ranging from 1 sec to 8 hrs.", options: { fontSize: 14, color: colors.secondary } }
    ], { x: 0.6, y: 1.3, w: 4.0, h: 0.8, valign: "top", margin: 0 });

    slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 2.4, w: 4.2, h: 1.0, fill: { color: colors.white }, shadow: getShadow() });
    slide2.addText([
        { text: "Step 2", options: { fontSize: 12, color: colors.accent, bold: true, breakLine: true } },
        { text: "Measure baseline & AI success", options: { fontSize: 16, color: colors.primary, bold: true, breakLine: true } },
        { text: "Time skilled humans, evaluate AI agent success rates.", options: { fontSize: 14, color: colors.secondary } }
    ], { x: 0.6, y: 2.5, w: 4.0, h: 0.8, valign: "top", margin: 0 });

    slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 3.6, w: 4.2, h: 1.0, fill: { color: colors.white }, shadow: getShadow() });
    slide2.addText([
        { text: "Step 3", options: { fontSize: 12, color: colors.accent, bold: true, breakLine: true } },
        { text: "Fit logistic model", options: { fontSize: 16, color: colors.primary, bold: true, breakLine: true } },
        { text: "Estimate task duration at which AI achieves 50% success.", options: { fontSize: 14, color: colors.secondary } }
    ], { x: 0.6, y: 3.7, w: 4.0, h: 0.8, valign: "top", margin: 0 });

    // Figure 2 on the right
    slide2.addImage({ path: "benchmark/assets/figure_2.jpg", x: 5.0, y: 1.2, w: 4.5, h: 3.4, sizing: { type: 'contain' } });
    slide2.addText("Methodology Overview", { x: 5.0, y: 4.7, w: 4.5, h: 0.3, fontSize: 12, color: "64748B", align: "center", italic: true });

    // SLIDE 3: Task Suite
    let slide3 = pres.addSlide({ masterName: "MASTER_SLIDE" });
    slide3.addText("170 Tasks Spanning 3 Seconds to 8 Hours of Human Effort", { placeholder: "title" });

    // Suite composition
    slide3.addText("Task Suite Composition", { x: 0.5, y: 1.1, w: 9, h: 0.4, fontSize: 18, color: colors.primary, bold: true, fontFace: 'Segoe UI' });

    let compTable = [
        [
            { text: "Suite", options: { bold: true, fill: { color: colors.primary }, color: colors.white } },
            { text: "Tasks", options: { bold: true, fill: { color: colors.primary }, color: colors.white } },
            { text: "Duration Range", options: { bold: true, fill: { color: colors.primary }, color: colors.white } },
            { text: "Description", options: { bold: true, fill: { color: colors.primary }, color: colors.white } }
        ],
